/** 缺省回退色：未预生成的组合退到这里，避免"静默空白" */
const FALLBACK_COLOR = 'text-3'

/** 开发期告警开关（生产构建里 process.env.NODE_ENV 会被替换成 'production'） */
const IS_DEV = (function () {
  try {
    return process.env.NODE_ENV !== 'production'
  } catch (e) {
    return false
  }
})()

function warnMissing(msg) {
  if (IS_DEV && typeof console !== 'undefined' && console.warn) console.warn('[Icon] ' + msg)
}

const px = computed(() => {
  const n = Number(props.size)
  return (Number.isFinite(n) && n > 0 ? n : 20) + 'px'
})

const uri = computed(() => {
  const key = props.name + '|' + props.color
  const hit = ICON_URI[key]
  if (hit) return hit

  // 回退 1：同名图标的默认色
  const fb = ICON_URI[props.name + '|' + FALLBACK_COLOR]
  if (fb) {
    warnMissing('颜色组合未预生成，已回退：' + key)
    return fb
  }

  // 回退 2：同名图标的任意已生成色
  const anyKey = Object.keys(ICON_URI).find(function (k) {
    return k.indexOf(props.name + '|') === 0
  })
  if (anyKey) {
    warnMissing('颜色组合未预生成，已回退：' + key + ' → ' + anyKey)
    return ICON_URI[anyKey]
  }

  warnMissing('图标名不存在：' + props.name)
  return ''
})

const iconStyle = computed(() => ({
  width: px.value,
  height: px.value,
  backgroundImage: uri.value ? 'url("' + uri.value + '")' : 'none',
  backgroundSize: '100% 100%',
  backgroundRepeat: 'no-repeat',
  backgroundPosition: 'center',
}))
</script>

